 const activityMarkup=a.length?`<div class="activity-chart">${a.slice(-7).map((x,i)=>`<div style="height:${Math.max(12,Math.min(100,(x.count||1)*18))}%;width:9%;background:linear-gradient(180deg,#8b83ff,#526dfe);border-radius:6px 6px 0 0" title="${x.date}"></div>`).join("")}</div><div class="activity-days">${a.slice(-7).map(x=>`<span class="chart-day">${new Date(`${x.date}T12:00:00`).toLocaleDateString(getLanguage(),{weekday:"short"})}</span>`).join("")}</div>`:`<div class="activity-chart"><div class="activity-empty"><span class="empty-illustration">↗</span><strong>${t("dashboard.noActivity")}</strong><span>${t("dashboard.noActivitySub")}</span></div></div>`;
 return `${heading(t("dashboard.eyebrow"),t("dashboard.title"),t("dashboard.subtitle"),`<span class="date-label">${new Date().toLocaleDateString(getLanguage(),{weekday:"long",day:"numeric",month:"long",year:"numeric"})}</span>`)}
 <section class="hero-card"><div class="hero-copy"><div class="hero-kicker">✦ &nbsp; ENGLISH LEARNING · B1.1</div><h2>${t("dashboard.title")}</h2><p>${t("dashboard.subtitle")}</p><a class="primary-button" href="#/lessons">${t("dashboard.start")} <span>→</span></a></div><div class="hero-orb"></div><div class="hero-symbol">Aa</div></section>
 <section class="stats-grid">
 ${stat(t("dashboard.statsLessons"),completed, t("dashboard.ofLessons"),"▤","blue")}
 ${stat(t("dashboard.statsExercises"),p.completedExercises?.length||0,t("dashboard.fromAttempts"),"✓","purple")}
 ${stat(t("dashboard.statsAccuracy"),attempts?accuracy+"%":"—",attempts?`${p.correct} / ${attempts} ${t("dashboard.fromAttempts")}`:t("dashboard.fromAttempts"),"◎","green")}
 ${stat(t("dashboard.statsWords"),words,t("dashboard.wordsSaved"),"文","orange")}
 ${stat(t("nav.games"),p.gamesPlayed||0,t("dashboard.gamesPlayed"),"◇","purple")}
 ${stat(t("nav.tests"),p.testsTaken||0,t("dashboard.testsTaken"),"▣","blue")}
 </section>
 <div class="dashboard-grid">
  <section class="panel"><div class="panel-heading"><div><h3>${t("dashboard.activity")}</h3><p>${t("dashboard.activitySub")}</p></div><span class="mini-tag">7 DAYS</span></div>${activityMarkup}</section>
  <section class="panel"><div class="panel-heading"><div><h3>${t("dashboard.quick")}</h3><p>${t("dashboard.dailySub")}</p></div></div>
   <a class="daily-card" href="#/lessons"><span class="daily-icon">▤</span><span><strong>${t("dashboard.openLessons")}</strong><small>${t("dashboard.continueSub")}</small></span><span class="arrow">→</span></a>
   <a class="daily-card" href="#/grammar"><span class="daily-icon">Aa</span><span><strong>${t("sections.grammar")}</strong><small>${t("dashboard.dailySub")}</small></span><span class="arrow">→</span></a>
   <a class="daily-card" href="#/vocabulary"><span class="daily-icon">文</span><span><strong>${t("sections.vocabulary")}</strong><small>${t("dashboard.dailySub")}</small></span><span class="arrow">→</span></a>
   <a class="daily-card" href="#/speaking"><span class="daily-icon">♫</span><span><strong>${t("nav.speaking")}</strong><small>${t("dashboard.dailySub")}</small></span><span class="arrow">→</span></a>
   <a class="daily-card" href="#/progress"><span class="daily-icon">↗</span><span><strong>${t("nav.progress")}</strong><small>${t("dashboard.activitySub")}</small></span><span class="arrow">→</span></a>
  </section>
 </div>
 <div class="section-heading"><h2>${t("dashboard.lessonsTitle")}</h2><a href="#/lessons">${t("dashboard.viewAll")} →</a></div>
 <section class="lesson-grid">${lessonData.slice(0,3).map((l,i)=>lessonCard(l,i,p)).join("")}</section>`;
