function localized(obj){return obj?.[getLanguage()]||obj?.en||""}
function lessonCard(l,i,p){const id=courseLessons[i].id,done=p.completedLessons?.includes(id);return `<a class="lesson-card" href="#/lessons/${id}" style="text-decoration:none;color:inherit"><div class="lesson-number">${String(i+1).padStart(2,"0")}</div><h3>${localized(courseLessons[i].title)}</h3><p>${localized(courseLessons[i].focus)}</p><div class="lesson-meta"><span>${done?"✓ ":""}${done?(getLanguage()==="sr"?"Završeno":getLanguage()==="ru"?"Завершён":"Completed"):t("dashboard.notStarted")}</span><span>${t("dashboard.lesson")} ${i+1} →</span></div></a>`}
function lessons(){const p=getProgress();return `${heading(t("dashboard.eyebrow"),t("dashboard.lessonsTitle"),t("dashboard.lessonsSub"))}<section class="lesson-grid">${courseLessons.map((l,i)=>lessonCard([l.title.en,l.focus.en],i,p)).join("")}</section>`}
function lessonDetail(id){const l=courseLessons.find(x=>x.id===id);if(!l)return lessons();const lang=getLanguage(),p=getProgress();return `${heading(t("nav.lessons"),localized(l.title),localized(l.focus),`<a class="secondary-button" href="#/lessons">← ${t("nav.lessons")}</a>`)}
 <div class="content-columns"><section class="panel"><h3>${lang==="sr"?"Šta ćeš naučiti":lang==="ru"?"Чему вы научитесь":"Learning objectives"}</h3><ul class="content-list">${l.objectives[lang].map(x=>`<li>${x}</li>`).join("")}</ul><h3>${lang==="sr"?"Gramatika":lang==="ru"?"Грамматика":"Grammar"}</h3><div class="tag-list">${l.grammar.map(id=>{const g=grammarTopics.find(x=>x.id===id);return `<a class="topic-tag" href="#/grammar/${id}">${g?.title||id}</a>`}).join("")}</div><h3>${lang==="sr"?"Tematski vokabular":lang==="ru"?"Тематическая лексика":"Vocabulary topics"}</h3><div class="tag-list">${l.vocabulary.map(v=>`<span class="topic-tag">${v.replaceAll("-"," ")}</span>`).join("")}</div></section>
 <section class="panel"><h3>${lang==="sr"?"Kratak razgovor":lang==="ru"?"Короткий диалог":"Short dialogue"}</h3>${l.dialogue.map(line=>`<div class="dialogue-line"><strong>${line.speaker}</strong><p>${line.en}</p><small>${line[lang]}</small></div>`).join("")}</section></div>
 ${renderLessonTeaching(lessonContent[l.id]||[],lang)}
 <section class="panel practice-panel"><h3>${lang==="sr"?"Govorna vežba":lang==="ru"?"Устная практика":"Speaking practice"}</h3><p>${l.practice[lang]}</p><button class="primary-button" id="complete-lesson">${lang==="sr"?"Označi lekciju kao završenu":lang==="ru"?"Отметить урок как завершённый":"Mark lesson as completed"}</button></section>`}
function renderLessonTeaching(sections,lang){
 const label=lang==="sr"?"Detaljno gradivo":lang==="ru"?"Подробный учебный материал":"Detailed lesson material";
 const exampleLabel=lang==="sr"?"Primeri":lang==="ru"?"Примеры":"Examples";
 const tipLabel=lang==="sr"?"Zapamti":lang==="ru"?"Важно":"Remember";
 return `<section class="lesson-teaching"><div class="section-heading"><h2>${label}</h2><span class="mini-tag">${sections.length} ${lang==="sr"?"celina":lang==="ru"?"разделов":"sections"}</span></div>${sections.map((section,index)=>`<article class="panel teaching-card"><div class="teaching-number">${String(index+1).padStart(2,"0")}</div><h3>${section.title[lang]||section.title.en}</h3><p class="teaching-intro">${section.body[lang]||section.body.en}</p>${section.table?`<div class="table-wrap"><table class="frequency-table"><thead><tr>${section.table.headers[lang].map(h=>`<th>${h}</th>`).join("")}</tr></thead><tbody>${section.table.rows.map(row=>`<tr><td>${row.frequency[lang]}</td><td><strong>${row.main[lang]}</strong></td><td>${row.related[lang]}</td></tr>`).join("")}</tbody></table></div>`:""}${section.items?`<div class="phrase-list">${section.items.map(item=>`<div class="phrase-item"><div class="phrase-name">${item.phrase}</div><p>${item.meaning[lang]||item.meaning.en}</p><div class="phrase-example"><strong>${exampleLabel}</strong><span>${item.example.en}</span><small>${item.example[lang]||item.example.en}</small></div></div>`).join("")}</div>`:""}${section.examples?`<h4>${exampleLabel}</h4><div class="teaching-examples">${section.examples.map(item=>`<div class="teaching-example"><p>${item.en.replaceAll("\n","<br>")}</p><small>${(item[lang]||item.en).replaceAll("\n","<br>")}</small>${item.note?`<small>${item.note}</small>`:""}</div>`).join("")}</div>`:""}${section.tip?`<div class="teaching-tip"><strong>${tipLabel}</strong><p>${section.tip[lang]||section.tip.en}</p></div>`:""}</article>`).join("")}</section>`;
}
function grammar(){const lang=getLanguage();return `${heading(t("nav.grammar"),lang==="sr"?"Gramatika B1.1":lang==="ru"?"Грамматика B1.1":"B1.1 Grammar","Clear explanations, structures, examples and common mistakes.")}<div class="topic-list">${grammarTopics.map(g=>`<details class="topic-card" id="${g.id}"><summary><span><strong>${g.title}</strong><small>${g.level} · ${g.signals.slice(0,4).join(" · ")}</small></span><span class="topic-chevron">＋</span></summary><div class="topic-body"><p>${localized(g.use)}</p><div class="grammar-forms">${g.forms.map(f=>`<div><small>${f.label}</small><code>${f.pattern}</code></div>`).join("")}</div><h4>${lang==="sr"?"Primeri":lang==="ru"?"Примеры":"Examples"}</h4><ul>${g.examples.map(e=>`<li>${e}</li>`).join("")}</ul><h4>${lang==="sr"?"Česte greške":lang==="ru"?"Типичные ошибки":"Common mistakes"}</h4>${g.mistakes.map(m=>`<div class="mistake"><span class="wrong">✕ ${m.wrong}</span><span class="right">✓ ${m.right}</span><small>${m.why}</small></div>`).join("")}<button class="secondary-button grammar-reviewed ${getProgress().completedGrammar?.includes(g.id)?"active":""}" data-grammar-reviewed="${g.id}">${getProgress().completedGrammar?.includes(g.id)?(lang==="sr"?"Obrađeno":lang==="ru"?"Повторено":"Reviewed"):(lang==="sr"?"Označi kao obrađeno":lang==="ru"?"Отметить как повторённое":"Mark as reviewed")}</button></div></details>`).join("")}</div>`}
function vocabulary(){const lang=getLanguage();const categories=[...new Set(vocabularyWords.map(v=>v.category))].sort();const categoryNames={"daily-life":{sr:"Svakodnevni život",ru:"Повседневная жизнь",en:"Daily life"},work:{sr:"Posao",ru:"Работа",en:"Work"},education:{sr:"Obrazovanje",ru:"Образование",en:"Education"},feelings:{sr:"Osećanja",ru:"Чувства",en:"Feelings"},relationships:{sr:"Odnosi",ru:"Отношения",en:"Relationships"},food:{sr:"Hrana",ru:"Еда",en:"Food"},shopping:{sr:"Kupovina",ru:"Покупки",en:"Shopping"},money:{sr:"Novac",ru:"Деньги",en:"Money"},health:{sr:"Zdravlje",ru:"Здоровье",en:"Health"},travel:{sr:"Putovanja",ru:"Путешествия",en:"Travel"},technology:{sr:"Tehnologija",ru:"Технологии",en:"Technology"},environment:{sr:"Životna sredina",ru:"Окружающая среда",en:"Environment"},media:{sr:"Mediji",ru:"Медиа",en:"Media"},society:{sr:"Društvo",ru:"Общество",en:"Society"},communication:{sr:"Komunikacija",ru:"Общение",en:"Communication"},"phrasal-verbs":{sr:"Frazni glagoli",ru:"Фразовые глаголы",en:"Phrasal verbs"},adjectives:{sr:"Pridevi",ru:"Прилагательные",en:"Adjectives"},adverbs:{sr:"Prilozi",ru:"Наречия",en:"Adverbs"},introductions:{sr:"Predstavljanje",ru:"Знакомство",en:"Introductions"},"personal-information":{sr:"Lični podaci",ru:"Личная информация",en:"Personal information"},"daily-routines":{sr:"Dnevne rutine",ru:"Повседневные дела",en:"Daily routines"},"life-events":{sr:"Životni događaji",ru:"Жизненные события",en:"Life events"},experiences:{sr:"Iskustva",ru:"Опыт",en:"Experiences"},achievements:{sr:"Postignuća",ru:"Достижения",en:"Achievements"},news:{sr:"Vesti",ru:"Новости",en:"News"},memories:{sr:"Sećanja",ru:"Воспоминания",en:"Memories"},"unexpected-events":{sr:"Neočekivani događaji",ru:"Неожиданные события",en:"Unexpected events"},emails:{sr:"Imejlovi",ru:"Электронные письма",en:"Emails"},"work-communication":{sr:"Poslovna komunikacija",ru:"Деловое общение",en:"Work communication"},transport:{sr:"Prevoz",ru:"Транспорт",en:"Transport"},procedures:{sr:"Procedure",ru:"Процедуры",en:"Procedures"},"adjectives":{sr:"Pridevi",ru:"Прилагательные",en:"Adjectives"}};const all=lang==="sr"?"Sve teme":lang==="ru"?"Все темы":"All topics";return `${heading(t("nav.vocabulary"),lang==="sr"?"B1.1 rečnik":lang==="ru"?"Словарь B1.1":"B1.1 Vocabulary",lang==="sr"?"Prošireni tematski rečnik sa prevodima, primerima, pretragom i opcionalnim rečničkim podacima.":lang==="ru"?"Расширенный тематический словарь с переводами, примерами, поиском и дополнительными словарными данными.":"An expanded topic-based vocabulary with translations, examples, search and optional dictionary details.")}<div class="vocab-summary"><strong>${vocabularyWords.length}</strong><span>${lang==="sr"?"reči i izraza":lang==="ru"?"слов и выражений":"words and expressions"}</span><small>${categories.length} ${lang==="sr"?"tematskih oblasti":lang==="ru"?"тематических разделов":"topic areas"}</small></div><div class="vocab-toolbar"><input id="vocab-search" type="search" placeholder="${lang==="sr"?"Pretraži englesku reč, prevod ili primer…":lang==="ru"?"Поиск английского слова, перевода или примера…":"Search an English word, translation or example…"}"><select id="vocab-category"><option value="">${all}</option>${categories.map(c=>`<option value="${c}">${categoryNames[c]?.[lang]||c.replaceAll("-"," ")}</option>`).join("")}</select><select id="vocab-status"><option value="all">${lang==="sr"?"Sve reči":lang==="ru"?"Все слова":"All words"}</option><option value="new">${lang==="sr"?"Nije označeno kao naučeno":lang==="ru"?"Не изучено":"Not learned"}</option><option value="learned">${lang==="sr"?"Naučeno":lang==="ru"?"Изучено":"Learned"}</option></select><span id="vocab-count">${vocabularyWords.length} / ${vocabularyWords.length}</span></div><div id="vocab-list" class="vocab-list">${vocabularyWords.map(v=>vocabRow(v,lang)).join("")}</div><p class="vocab-api-note">${lang==="sr"?"Dodatna definicija i izgovor dostupni su na zahtev preko Free Dictionary API-ja. Osnovni rečnik i prevodi rade i bez interneta.":lang==="ru"?"Дополнительное определение и произношение доступны по запросу через Free Dictionary API. Основной словарь работает и без интернета.":"Optional definitions and pronunciation are fetched on demand from the Free Dictionary API. Core vocabulary and translations work offline."}</p>`}
function vocabRow(v,lang){const learned=Boolean(getProgress().vocabulary?.[v.id]);const label=lang==="sr"?(learned?"Usvojeno":"Označi kao usvojeno"):lang==="ru"?(learned?"Выучено":"Отметить как выученное"):(learned?"Learned":"Mark as learned");const lookupable=!v.word.includes(" ")&&/^[a-z'-]+$/i.test(v.word);return `<article class="vocab-row ${learned?"is-learned":""}" data-category="${v.category}" data-learned="${learned}" data-search="${[v.word,v.translation.sr,v.translation.ru,v.definition||"",v.category,v.example||""].join(" ").toLowerCase()}"><div><strong>${v.word}</strong><small>${v.partOfSpeech} · ${v.category.replaceAll("-"," ")}</small><button class="vocab-learn ${learned?"active":""}" data-vocab-learn="${v.id}">${label}</button>${lookupable?`<button class="vocab-dictionary" data-dictionary="${v.word}">${lang==="sr"?"Definicija / izgovor":lang==="ru"?"Определение / произношение":"Definition / pronunciation"}</button>`:""}<div class="dictionary-result" id="dictionary-${v.id}" aria-live="polite"></div></div><div><strong>${v.translation[lang]||v.translation.en||""}</strong>${v.definition?`<small>${v.definition}</small>`:""}<em>${v.example||""}</em></div></article>`}
