 en:{eyebrow:"PRACTICE CENTRE",title:"B1.1 practice centre",subtitle:"A large question bank with a fresh random session every time you start.",start:"Start a new session",check:"Check answer",next:"Next question",finish:"See results",restart:"New random session",type:"Type your answer",correct:"Correct",incorrect:"Not quite",answer:"Correct answer",complete:"Session complete",score:"Your score",of:"of",empty:"Select an answer or enter a response to continue.",count:"Questions per session",mode:"Practice focus",mixed:"Mixed practice",grammar:"Grammar only",vocabulary:"Vocabulary only",bank:"Available questions",noRepeat:"Questions are selected without repetition within a session.",question:"Question",right:"Correct answers",wrong:"Incorrect answers",accuracy:"Accuracy",all:"All available",time:"No time limit",feedback:"Explanation"},
