 if(route==="vocabulary"){const search=document.querySelector("#vocab-search"),category=document.querySelector("#vocab-category"),status=document.querySelector("#vocab-status"),list=document.querySelector("#vocab-list"),count=document.querySelector("#vocab-count");const applyFilters=()=>{const q=search.value.trim().toLowerCase();let visible=0;list.querySelectorAll(".vocab-row").forEach(row=>{const matchesText=row.dataset.search.includes(q),matchesCategory=!category.value||row.dataset.category===category.value,matchesStatus=status.value==="all"||(status.value==="learned"?row.dataset.learned==="true":row.dataset.learned!=="true");const show=matchesText&&matchesCategory&&matchesStatus;row.hidden=!show;if(show)visible++;});count.textContent=`${visible} / ${vocabularyWords.length}`;};search.addEventListener("input",applyFilters);category.addEventListener("change",applyFilters);status.addEventListener("change",applyFilters);list.querySelectorAll("[data-vocab-learn]").forEach(button=>button.addEventListener("click",()=>{const p=getProgress(),words={...(p.vocabulary||{})},id=button.dataset.vocabLearn;if(words[id])delete words[id];else{words[id]=localDateKey();recordActivity({date:localDateKey(),count:1,vocabulary:id});}saveProgress({...p,vocabulary:words});renderPage("vocabulary");}));list.querySelectorAll("[data-dictionary]").forEach(button=>button.addEventListener("click",async()=>{const word=button.dataset.dictionary,result=document.querySelector(`#dictionary-${CSS.escape(vocabularyWords.find(v=>v.word===word)?.id||"")}`);if(!result)return;if(result.dataset.loaded==="true"){result.hidden=!result.hidden;return;}button.disabled=true;button.textContent=getLanguage()==="sr"?"Učitavanje…":getLanguage()==="ru"?"Загрузка…":"Loading…";try{const response=await fetch(`https://api.dictionaryapi.dev/api/v2/entries/en/${encodeURIComponent(word)}`);if(!response.ok)throw new Error("No dictionary entry was returned.");const data=await response.json(),entry=data[0],phonetic=entry.phonetic||entry.phonetics?.find(x=>x.text)?.text||"",audio=entry.phonetics?.find(x=>x.audio)?.audio,definitions=(entry.meanings||[]).flatMap(m=>(m.definitions||[]).slice(0,2).map(d=>({part:m.partOfSpeech,definition:d.definition,example:d.example}))).slice(0,4);result.replaceChildren();if(phonetic){const ph=document.createElement("strong");ph.textContent=phonetic;result.append(ph);}definitions.forEach(d=>{const line=document.createElement("p");line.textContent=`${d.part}: ${d.definition}`;result.append(line);if(d.example){const ex=document.createElement("small");ex.textContent=`“${d.example}”`;result.append(ex);}});if(audio){const play=document.createElement("button");play.className="vocab-audio";play.textContent="▶ Play pronunciation";play.addEventListener("click",()=>new Audio(audio).play());result.append(play);}if(!definitions.length)throw new Error("No definitions were available.");result.dataset.loaded="true";result.hidden=false;button.textContent=getLanguage()==="sr"?"Sakrij rečničke podatke":getLanguage()==="ru"?"Скрыть словарные данные":"Hide dictionary details";}catch(error){result.textContent=getLanguage()==="sr"?"Rečnički podaci trenutno nisu dostupni. Proveri internet vezu ili pokušaj ponovo.":getLanguage()==="ru"?"Словарные данные сейчас недоступны. Проверьте подключение к интернету и повторите попытку.":"Dictionary data is currently unavailable. Check your connection and try again.";result.hidden=false;button.textContent=getLanguage()==="sr"?"Pokušaj ponovo":getLanguage()==="ru"?"Повторить":"Try again";}finally{button.disabled=false;}}));}
